mapper.select:
SELECT FROM crawl_target
enabled = #{enabled}
ORDER BY updated_at DESC, id DESC

SELECT id, target_id, url, title, content, url_hash, content_hash, status, http_status, error_message, fetched_at, created_at
FROM crawl_document


        target_id = #{targetId}


ORDER BY fetched_at DESC, id DESC
LIMIT #{limit}

SELECT 
FROM crawl_run_log


        target_id = #{targetId}


        AND status = #{status}


        AND failure_code = #{failureCode}


ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT 
FROM crawl_run_log
WHERE status = 'FAILED'

    AND reviewed = #{reviewed}


    AND failure_code = #{failureCode}

ORDER BY created_at DESC, id DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM crawl_document
WHERE created_at < #{cutoff}
  AND status IN ('FAILED', 'DUPLICATE')
